def P(t,sty='BodyA'): return Paragraph(t,S[sty])
def bullet(t): return P('&bull;&nbsp; '+t)
def mk_table(rows,widths,header=True):
    t=Table(rows,colWidths=widths,repeatRows=1 if header else 0,hAlign='LEFT')
    st=[('VALIGN',(0,0),(-1,-1),'TOP'),('GRID',(0,0),(-1,-1),.35,LINE),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)]
    if header: st.append(('BACKGROUND',(0,0),(-1,0),INK))
    for r in range(1 if header else 0,len(rows)):
        if r%2==0: st.append(('BACKGROUND',(0,r),(-1,r),PALE))
    t.setStyle(TableStyle(st)); return t
def row(vals,head=False): return [P(str(v),'HeadCellA' if head else 'CellA') for v in vals]
def hf(c,d):
    c.saveState();w,h=A4
    if d.page>1:
        c.setStrokeColor(LINE);c.setLineWidth(.45);c.line(18*mm,h-15*mm,w-18*mm,h-15*mm)
        c.setFont('Helvetica',7);c.setFillColor(MUTED);c.drawString(18*mm,h-11.5*mm,'SMART REFRIGERATOR MANAGER | SCRUMDESK GUIDE');c.drawRightString(w-18*mm,10*mm,str(d.page))
    c.restoreState()
def story_card(ident,title,story,points,priority,ac,tasks,owner='Sabind (coding); Harsha (review/evidence)',deps=''):
    return [P(f'{ident}  {title}','H2A'),P(story,'StoryA'),P(f'<b>Priority:</b> {priority} &nbsp; <b>Estimate:</b> {points} points &nbsp; <b>Owner split:</b> {owner}<br/><b>Depends on:</b> {deps or "None"}','SmallA'),P('<b>Acceptance criteria</b>','SmallA')]+[bullet(x) for x in ac]+[P('<b>Implementation and evidence tasks</b>','SmallA'),mk_table([row(['Task','Type','Assigned'],True)]+[row(x) for x in tasks],[86*mm,27*mm,48*mm]),Spacer(1,4*mm)]

doc=SimpleDocTemplate(str(OUT),pagesize=A4,rightMargin=18*mm,leftMargin=18*mm,topMargin=22*mm,bottomMargin=17*mm,title='ScrumDesk Implementation Playbook',author='Smart Refrigerator Manager Project Team')
