s += [P('A practical, step-by-step guide for translating this enhancement into a ScrumDesk project: project goal, epics, stories, acceptance criteria, sprint planning, task assignment, daily tracking, release evidence, and assessment close-out.','BodyA'),Spacer(1,4*mm)]
cover=[row(['Project','Details'],True),row(['Product','Existing Smart Refrigerator Manager web app (Spring Boot / Thymeleaf)']),row(['Release goal','English/Japanese UX, waste history, inventory-based AI menu ideas, and account/profile essentials']),row(['Prepared','10 November 2026']),row(['Named members','Sabind Daryal (all coding); Harsha (surname / student ID to confirm)']),row(['Submission deadline','22 December 2026, 23:59, per supplied CN7021 brief']),row(['Board state','Guide and backlog specification prepared; live ScrumDesk workspace not connected or verified'])]
s.append(mk_table(cover,[43*mm,118*mm],header=False));s += [Spacer(1,7*mm),P('Use this as the source of truth for entering cards. Keep unfinished work open until acceptance evidence exists. A code change by itself does not make a story Done.','CallA'),P('Important course constraint','H2A'),P('The supplied brief specifies groups of three or four. Only Sabind and Harsha were named. Confirm the official group roster and any additional member(s) with the tutor; do not fabricate names, hours, signatures, or ScrumDesk activity. The proposed allocation keeps Sabind as the sole coder and assigns Harsha non-coding requirements, board, acceptance-evidence, minutes, and report work.','BodyA'),PageBreak()]

s += [P('1. Release goal, scope and evidence rule','H1A'),P('<b>Product goal:</b> Help a signed-in household user understand what is in the fridge, act on food nearing expiry, record what is discarded, and get meal ideas from current stock in English or Japanese.','BodyA'),P('<b>Release goal:</b> Ship the web enhancement with complete locale handoff from the login screen into the dashboard; consistently localized labels, placeholders, validation and dynamic text; a polished Apple-inspired responsive UI; user-owned waste history; inventory-aware menu suggestions with an optional configured AI provider and safe local fallback; and account/profile/recovery flows. Flutter QR scanning stays outside this release.','BodyA'),P('In scope','H2A')]
for x in ['Locale choice on login/signup/recovery is carried through successful login; after login, it is saved as the account language. Profile changes persist and survive a later sign-in.','English and Japanese cover visible UI, HTML placeholders, accessibility labels, form errors, category/status labels, dates, dynamic empty states, waste history labels, and menu text. User-entered food names and reasons remain user content.','Waste actions create owner-scoped history and update active stock transactionally. Users can view history and total discarded quantity.','Menu service matches local inventory, considers expiry where available, requests output in the user language when an external provider is explicitly configured, and falls back locally when no key or provider failure.','Account scope includes email-based registration, profile name/language, and single-use time-limited email reset codes. Flutter/mobile work is excluded.']:
    s.append(bullet(x))
s += [P('Board status discipline','H2A'),P('At guide creation, code for several baseline features already exists, but current language handoff and visual redesign are being completed, and end-to-end acceptance tests are still required. Create or update cards as <b>In Progress</b> or <b>Review</b>, then move to <b>Done</b> only after the acceptance criteria below pass and the evidence is attached. No live board, branch history, CI run, or ScrumDesk screenshot has been verified.','CallA')]

s += [P('2. Create and configure the ScrumDesk project','H1A')]
setup=[['Step','Action in ScrumDesk','Value / output'],['1','Create a new project','Name: Smart Refrigerator Manager - Release 2. Description: continuation of existing open-source web app; release scope is this guide.'],['2','Set project goal and stakeholders','Goal from Section 1. Add official team members only after checking Moodle/tutor roster, IDs and group number. Identify the official group leader.'],['3','Create release / version','Release: R2 - English, Waste and Menu. Target window: 10 Nov to 21 Dec 2026 for implementation/evidence freeze; submission 22 Dec.'],['4','Create backlog hierarchy','Create the five Epics in Section 3, then Features if the chosen edition supports them. Add the user stories under each Epic. ScrumDesk documentation supports Epics, Features and User Stories; the depth varies by edition.'],['5','Set backlog item templates','Add fields to story template: ID, user story, outcome/value, priority/order, story points, acceptance criteria, dependencies, privacy/security notes, owner split, evidence link, and Done checklist.'],['6','Set workflow states','Use the states supported in the project: Backlog / Ready / In Progress / Review / Done / Blocked. If ScrumDesk edition uses different names, map these states and record the mapping.'],['7','Create team capacity','Enter actual member availability, absences and non-coding workload. Do not treat estimated story points as hours. Sabind codes; Harsha owns review/coordination/documentation tasks.'],['8','Create sprints','Create sprint dates and goal in PLAN. Pull ready items into the sprint, check capacity, then break items down into tasks in WORK. ScrumDesk’s current manual describes PLAN and WORK for planning and task tracking.'],['9','Set evidence conventions','Attach test output, screenshots, report excerpt, meeting minute, code/commit link, or measured metric directly to a card; link related evidence from the report.']]
s.append(mk_table([row(setup[0],True)]+[row(x) for x in setup[1:]],[11*mm,50*mm,100*mm]))
s += [P('ScrumDesk’s official manual describes backlog hierarchy, epics/features, story templates, ordering, sprint creation in PLAN, sprint goals/date fields, capacity indicators, task decomposition, and WORK-view task tracking. Menu names can vary with the edition/version. Follow the feature available in your actual account and capture a screenshot of the final board. [1, 2, 3]','SmallA'),PageBreak()]

s += [P('3. Epic map and backlog order','H1A')]
epics=[['Epic','Outcome / boundary','Target release'],['E1 - Bilingual Experience and Apple-Inspired UI','A user can choose English/Japanese before login and keep that language after login; every visible product string is translated; screens share a polished responsive visual system.','R2'],['E2 - Food Waste History','A user records discarded stock, sees their own history and waste summary, and keeps stock/history consistent.','R2'],['E3 - AI Menu Suggestions','A user gets recipe ideas in their selected language from their stock. Optional provider use is configured, transparent and resilient; local fallback works.','R2'],['E4 - Account and Profile Essentials','Registration, sign-in, editable display name/language, email identity and reset-by-email-code work securely.','R2'],['E5 - Quality, Release and Assessment Evidence','Testability, privacy/security, responsive regression, metrics, CI/repo evidence and report artifacts are ready for submission.','R2']]
