s += [P('Recommended top-to-bottom backlog order','H2A')]
for x in ['E1.1 Locale continuity and persistence; E1.2 complete English/Japanese coverage; E1.3 cohesive modern visual redesign.','E4.1 registration/email/profile data; E4.2 profile and saved locale; E4.3 password-reset OTP and operational limits.','E2.1 atomic waste recording; E2.2 history and totals; E2.3 ownership and empty/error states.','E3.1 local inventory matching; E3.2 configured AI provider, language/expiry prompt, timeout and fallback; E3.3 privacy/user notice.','E5.1 requirement-linked tests; E5.2 security and access isolation; E5.3 responsive/browser regression; E5.4 measured metrics, cost/COCOMO and submission evidence.']:
    s.append(bullet(x))
s += [P('Prioritise by dependency and value, then order cards by drag-and-drop. ScrumDesk backlog listings can group or sort by Epic, theme, member, MoSCoW, business value, effort, state, readiness, sprint and release; use only fields available in the selected edition. [2]','BodyA'),P('4. Detailed Epic E1 stories','H1A')]
s += story_card('E1.1','Carry login language into the dashboard','As a user, I want the language I choose before signing in to remain selected after login so I do not have to reset the interface.',5,'Must',['Choosing English on login, then signing in, opens the dashboard in English.','Choosing Japanese on login, then signing in, opens the dashboard in Japanese.','The chosen language is saved in the account profile after successful authentication.','If no login-page override was selected, the profile preference is used.','A later login restores the saved preference.'],[['Track pending locale before authentication','Development','Sabind'],['Apply selected locale after auth and update profile','Development','Sabind'],['Verify EN/JA sign-in scenarios; capture screen evidence','Testing','Harsha']],'Sabind codes; Harsha reviews scenarios/evidence','Existing login and profile endpoints')
s += story_card('E1.2','Translate all interface text and placeholders','As an English- or Japanese-speaking user, I want every control and message localized so no screen has accidental mixed-language UI.',5,'Must',['Login, signup, recovery, dashboard, profile, filters, category labels, empty states, prompts, buttons, validation and status labels translate.','HTML placeholders and aria labels change with the selected language.','CSS-generated Japanese text is removed or supplied via translated markup.','Browser date control follows the selected document language.','User-entered food names/reasons remain unchanged.'],[['Inventory audit of visible strings and pseudo-content','Analysis','Harsha'],['Complete message catalogue and data-i18n bindings','Development','Sabind'],['Check all screens in both languages; record gaps','Testing','Harsha']],'Sabind codes; Harsha owns string inventory/review','E1.1')
s += story_card('E1.3','Apple-inspired responsive system UI','As a household member, I want a calm, consistent interface that is easy to scan on phone and desktop.',8,'Should',['Auth screens and dashboard use a consistent type scale, spacing, buttons, cards, focus states and color semantics.','Inventory, AI ideas, waste history and profile remain usable at 360px width and desktop widths.','Keyboard focus, labels, contrast and semantic headings are retained.','No clipping, overlap, horizontal overflow or invisible actions in tested viewports.'],[['Define design tokens and reusable page/card states','Development','Sabind'],['Apply auth, profile, dashboard, inventory and history layout','Development','Sabind'],['Capture mobile/desktop screenshots; report accessibility issues','Review','Harsha']],'Sabind codes; Harsha reviews visual acceptance','E1.2')
s += [PageBreak(),P('5. Detailed Epic E2 stories','H1A')]
s += story_card('E2.1','Record food waste transactionally','As a user, I want to record what I discard so the active inventory and waste history stay accurate.',8,'Must',['A user can select an owned item, quantity and reason.','Quantity must be positive and no greater than stock.','Partial disposal decrements active quantity; full disposal removes the active food row.','The event stores food name/category snapshot, discarded quantity, reason, time and owner.','Event write and stock change commit together or roll back together.','Invalid quantity or another user’s item returns a safe error and changes nothing.'],[['Review service transaction and ownership boundary','Development','Sabind'],['Validate quantity and reason; persist event and stock update','Development','Sabind'],['Test partial/full/invalid/foreign-owner/rollback cases','Testing','Harsha review; Sabind test code']],'Sabind codes; Harsha reviews scenarios','Food and authenticated principal')
s += story_card('E2.2','View waste history and summary','As a user, I want to see recent disposal records and total waste quantity so I can understand what is being lost.',5,'Must',['History is newest first and only includes the authenticated user’s events.','Each row shows food name, quantity, reason and localized date.','Dashboard total updates after recording waste and on page load.','Empty state is localized and explains how history begins.','No password, reset code or other private user fields appear in JSON.'],[['Provide and review user-scoped history API','Development','Sabind'],['Build history panel and summary metric','Development','Sabind'],['Verify empty/populated view and account isolation','Testing','Harsha']],'Sabind codes; Harsha acceptance evidence','E2.1')
s += story_card('E2.3','Keep waste data isolated by account','As a user, I want my inventory and waste history private to my account.',3,'Must',['All read/write paths derive identity from server authentication.','Cross-account food/event requests are denied.','Serialized waste responses do not expose the linked User entity or credentials.'],[['Review repository and controller scope','Security','Sabind'],['Add negative access tests and inspect JSON','Testing','Sabind implements; Harsha records results']],'Sabind codes; Harsha tracks security evidence','E2.1, E2.2')
s += [P('6. Detailed Epic E3 stories','H1A')]
s += story_card('E3.1','Suggest meals from current stock','As a user, I want meal suggestions using what I already have so I can use food before it expires.',5,'Must',['Only positive-quantity items from the current user are considered.','Up to five suggestions show name, description, matched inventory names, score and preparation time.','Local fallback handles common English/Japanese names and empty or sparse stock.','Nearest expiry may influence selection where dates are available.','No inventory data is sent externally when AI settings are absent.'],[['Build local recipe/ingredient matcher and aliases','Development','Sabind'],['Render localized recommendation cards and empty state','Development','Sabind'],['Test matching, ranking and no-match cases','Testing','Harsha review']],'Sabind codes; Harsha acceptance review','Inventory and E1 locale')
s += story_card('E3.2','Add an optional AI provider with resilient fallback','As a user, I want richer menu ideas from an AI provider when the project is configured for it.',8,'Should',['Provider is enabled only by a non-empty secret and explicit endpoint/model config.','Prompt requests output in the saved user language, uses inventory names/quantities/categories/expiry, and avoids unlisted ingredients except common basics.','Expected response has bounded fields and maximum five entries.','No-key, provider error, invalid response and timeout fall back to local ideas.','API keys and inventory contents are not logged.'],[['Define environment-based provider config and timeout','Development','Sabind'],['Parse and bound response; catch provider and JSON errors','Development','Sabind'],['Test absent key, valid stub, invalid response and timeout','Testing','Sabind implements; Harsha records']],'Sabind codes; Harsha verifies privacy/acceptance','E3.1, E1.1')
s += story_card('E3.3','Explain recommendation data use and limitations','As a user, I want to know whether my fridge inventory is sent to an external provider and what a suggestion means.',3,'Must before AI enablement',['Local mode clearly states suggestions are based on available inventory.','If remote AI is enabled, a localized disclosure states that inventory metadata is sent to the configured service.','UI says suggestions are ideas and not allergy/nutrition or food-safety advice.','Do not enable production remote mode before provider/privacy review.'],[['Write bilingual disclosure and suggestion limitation','Analysis / content','Harsha draft; Sabind binds to UI'],['Review provider data fields and configuration','Privacy','Harsha tracks; Sabind supplies technical detail'],['Capture disclosures in both languages','Review','Harsha']],'Sabind implements wording; Harsha coordinates review','E3.2, E1.2')
s += [PageBreak(),P('7. Detailed Epics E4 and E5 stories','H1A')]
s += story_card('E4.1','Register with email and a usable password','As a new user, I want to create an account with a recovery email so I can use my own fridge and recover access.',5,'Must',['Username is 3-40 characters and unique.','Email has valid basic syntax, is normalized consistently and unique.','Password minimum is eight characters and stored only as a one-way hash.','Validation errors retain non-sensitive entered username/email.','Legacy accounts without email are identified for migration/backfill before enabling their recovery.'],[['Extend/validate account model and service','Development','Sabind'],['Keep controller errors translated and form labels localized','Development','Sabind'],['Verify duplicates, invalid fields, password storage','Testing','Sabind tests; Harsha records']],'Sabind coding; Harsha requirements review','Existing User entity and password encoder')
s += story_card('E4.2','Maintain profile name and language','As a signed-in user, I want my display name and language saved to my account.',3,'Must',['Profile is scoped to current user.','Display name is required and at most 60 characters.','Only English/Japanese values accepted.','Saved preference drives interface after next login unless user deliberately overrides at login.','Email is read-only in this iteration.'],[['Validate and persist profile settings','Development','Sabind'],['Synchronize language control with profile drawer','Development','Sabind'],['Verify update and next-login behavior','Testing','Harsha']],'Sabind coding; Harsha verifies','E1.1, E4.1')
s += story_card('E4.3','Reset password through email OTP','As a registered user, I want a one-time code sent to my email so I can regain access securely.',8,'Must',['Known and unknown addresses return the same confirmation text.','Code is generated securely, stored hashed, expires after 10 minutes, and cannot be reused.','Wrong/expired/used code is rejected; valid code updates hashed password.','User is sent to normal login after reset; no automatic login.','SMTP is environment-configured; dev-only log fallback is never described as production mail.','Attempt and request throttling must be implemented before production release.'],[['Implement request/verify/reset flow and generic response','Development','Sabind'],['Configure SMTP through environment variables','Development / Ops','Sabind'],['Test delivery, generic response, expiry, replay and failure','Testing','Harsha records; Sabind implements tests']],'Sabind codes; Harsha acceptance/security evidence','E4.1, mail provider')
s += story_card('E5.1','Automate service and integration checks','As the project team, we want requirement-linked tests so regressions are detected before release.',8,'Must',['Unit tests cover waste quantity/ownership, menu matching/fallback, profile validation and OTP expiry/reuse.','Integration tests cover registration, authenticated access, transaction behavior and serialized responses.','Existing inventory CRUD/login flows have regression coverage.','Maven build and test results are attached to stories and report traceability matrix.'],[['Add unit tests by feature service','Testing','Sabind'],['Add web/integration and ownership tests','Testing','Sabind'],['Review traceability links and evidence completeness','Review','Harsha']],'Sabind implements all tests/coding; Harsha tracks/reviews','E1-E4 feature completion')
s += story_card('E5.2','Run responsive and localization regression','As an assessor/user, I want consistent interactions across key screens and languages.',5,'Must',['Run login/signup/recovery/profile/dashboard/inventory/waste/menu at 360px and desktop.','Switch languages on auth, then log in; profile and dashboard reflect selection.','Buttons, date controls, alerts, table/card wrapping and focus states are usable.','Attach dated screenshots and manual steps/results.'],[['Prepare EN/JA viewport script','Testing','Harsha'],['Fix defects','Development','Sabind'],['Record final screenshots and retest','Evidence','Harsha']],'Sabind fixes/code; Harsha executes and records','E1.1-E1.3')
s += story_card('E5.3','Collect metrics and freeze submission evidence','As the group, we want a defensible record of quality, cost and contribution for the report.',5,'Must',['Record code size/count method, test pass rate, requirement coverage, endpoint timings and known defects.','Recalculate COCOMO from measured enhancement size and state cost/rate assumptions.','Report maps code, tests, backlog and contributions with stable evidence links.','Attach repository URL, commits/branches/CI, ScrumDesk board/sprint evidence, dated meeting minutes, signed participation agreement and contribution matrix.','Final report is 3,000 words +/-10%, contains COCOMO, PM docs, software metrics, cost estimation, testing, legal/ethical discussion and Harvard references (minimum 12 per supplied template).','Each student completes the separate 10-tutorial document required by the brief.'],[['Collect baseline and post-change data','Metrics','Sabind technical measures; Harsha records'],['Complete report, bibliography and contribution appendix','Documentation','Harsha coordinates; Sabind technical input'],['Check submission links, cover sheet and deadline','Release','Official group leader (confirm)']],'Harsha coordinates; Sabind supplies code/test evidence','E5.1, E5.2')

s += [PageBreak(),P('8. Sprint plan and planning workshop','H1A'),P('Use these as provisional dates to enter; adjust to actual team capacity and tutorial feedback. ScrumDesk’s sprint form supports a name, goal, start date and end date; sprint planning is performed in PLAN, and selected stories are decomposed into tasks for WORK. Check the sprint capacity indicators rather than pulling every card just because it is in the backlog. [1, 4]','BodyA')]
sprints=[['Sprint/window','Sprint Goal','Candidate stories','Review exit'],['S1 | 10-23 Nov','Make language and account UX coherent from auth through dashboard.','E1.1, E1.2, E1.3, E4.2','Both locales verified; modern visual screens reviewed; profile persistence evidence attached.'],['S2 | 24 Nov-7 Dec','Record and review disposal safely.','E2.1, E2.2, E2.3, E4.1','Partial/full waste and ownership evidence; account registration scenarios pass.'],['S3 | 8-15 Dec','Deliver resilient menu ideas and complete reset security.','E3.1, E3.2, E3.3, E4.3','Local and configured AI/fallback cases; OTP expires/consumes; privacy disclosure reviewed.'],['Hardening | 16-20 Dec','Close release quality and assessment evidence.','E5.1, E5.2, E5.3; all defect stories','Regression/metrics/report/board evidence reviewed; unresolved defects listed.'],['Submission prep | 21 Dec','Freeze approved files and confirm submission handoff.','Final report and tutorial/participation artifacts','Official group leader verifies upload/package and acknowledges to group.']]
