for x in ['Open the sprint and review each selected story against acceptance criteria; demonstrate the feature in the running app.','Attach test logs, issue references, screen captures and any change in scope. Show the Done/Incomplete split.','Capture ScrumDesk sprint report with story statuses and effort. ScrumDesk manual describes sprint report fields for items and status; use the report available in the team edition. [5]','Move incomplete stories back to backlog or a later sprint and re-estimate/reorder with team discussion. Do not mark partially implemented cards Done.']:
    s.append(bullet(x))
s += [P('Retrospective','H2A')]
for x in ['Ask what helped, what caused delays/defects, and what the team will try next sprint.','Choose one or two measurable improvement actions with owner and date.','Record actions in ScrumDesk or linked meeting minutes; follow up at the next retrospective.']:
    s.append(bullet(x))
s += [P('Release and assessment close-out checklist','H2A')]
close=[['Check','ScrumDesk / submission evidence'],['Features complete','All Must stories Done; Should stories accepted or explicitly deferred; no hidden blockers.'],['Quality','Java 21 build/test run; results and defects attached; manual EN/JA and responsive flows checked.'],['Data and security','Ownership tests, OTP expiry/reuse, privacy notes, secrets handling, external AI setting and fallback documented.'],['Metrics and cost','Baseline/post-change measure method/results; measured KLOC; COCOMO recalculation; assumptions and cost rate clear.'],['Version control / CI','Repository accessible to tutor/module leader; dated branches/commits show collaboration; CI build/test result attached.'],['Project report','3,000 words +/-10%; use supplied template; analysis, architecture/UML/use cases, testing, COCOMO, PM, metrics, cost, legal/ethical and Harvard references.'],['Individual tutorials','Each student submits the required ten tutorial tasks document separately as described in brief.'],['Contributions','Who-did-what table with actual task/hour evidence; each member participation agreement completed and signed.'],['Submission','Cover sheet, source code/asset link or complete source archive, report PDF/DOCX and confirmation from official group leader by 22 Dec 2026 23:59.']]
s.append(mk_table([row(close[0],True)]+[row(x) for x in close[1:]],[39*mm,122*mm]))
s += [P('11. Roles and responsibility split','H1A')]
roles=[['Work','Sabind Daryal','Harsha'],['Backend/frontend/data model/integration','Sole coding owner','No coding assigned'],['Automated tests and defect fixes','Implements test code and fixes','Reviews requirements/test evidence; records result'],['Requirements/story acceptance','Technical input','Maintains criteria, backlog and review evidence'],['ScrumDesk board','Supplies code status; links commits','Board setup, ordering, sprint records, screenshots'],['Minutes and contribution log','Reports own activity truthfully','Maintains dated minutes, hours and evidence for all members'],['Report and submission','Technical architecture/code/test input','Coordinates report, references, appendices and checklist']]
s.append(mk_table([row(roles[0],True)]+[row(x) for x in roles[1:]],[51*mm,55*mm,55*mm]))
s += [P('Do not claim equal contribution just because a planned allocation says so. Enter actual hours and work evidence. The two named-member plan conflicts with the supplied brief’s 3-4 person team condition; confirm group membership, group leader and contribution expectations with the tutor.','CallA'),P('12. Metrics and definition of ready/done','H1A')]
s += [P('<b>Definition of Ready:</b> user value is stated; story is correctly nested under an Epic; acceptance criteria are testable; scope is small; language/security/privacy implications and dependencies are explicit; estimate and priority/order exist; test/evidence approach is known; owner split is possible.','BodyA'),P('<b>Definition of Done:</b> feature code is reviewed; relevant automated tests pass; all acceptance criteria pass; ownership and error handling are checked; English/Japanese strings, placeholders and accessible names are complete; responsive screenshots are clean; secrets are not exposed; report/traceability and board links are updated. For optional remote AI, provider failure fallback and data disclosure also pass.','BodyA')]
metric=[['Measure','How to collect in ScrumDesk / repo','Release target'],['Requirement coverage','Map story IDs to requirement IDs and test IDs; count covered Must requirements.','100% Must stories have test evidence or approved defer reason.'],['Test pass rate','Attach Maven test report; pass / executed.','100% for release-gate tests; report skipped tests honestly.'],['Waste correctness','Scenario checks for partial/full quantity, rollback and owner isolation.','All mandatory scenarios pass.'],['Localization gaps','Checklist of screens/placeholders/validation/dynamic states in EN and JA.','No unexplained untranslated UI strings.'],['Performance','Time local menu/history APIs with fixed data set; report p50/p95 and machine.','Target in project pack; record measured value and limits.'],['Cost/size','Measure net new source LOC and actual logged effort; calculate COCOMO assumptions.','No fabricated actual cost; separate forecast from actual.']]
s.append(mk_table([row(metric[0],True)]+[row(x) for x in metric[1:]],[37*mm,86*mm,38*mm]))

s += [PageBreak(),P('Appendix A. Ready-to-copy story template','H1A'),P('<b>ID and title:</b> ____<br/><b>Epic / feature:</b> ____<br/><b>User story:</b> As a [user], I want [capability] so that [value].<br/><b>Priority/order:</b> ____ <b>Estimate (story points):</b> ____ <b>Release/sprint:</b> ____<br/><b>Acceptance criteria:</b> Given/When/Then statements with observable outcomes.<br/><b>Dependencies:</b> ____ <b>Risks/privacy/security:</b> ____<br/><b>Owner split:</b> Coding: Sabind; review/evidence/board: Harsha; update if official roster differs.<br/><b>Tasks:</b> one action, type, assignee, estimate, acceptance/evidence link each; coding/test tasks assigned only per agreed split.<br/><b>Evidence links:</b> commit/PR ____; test output ____; screenshot ____; report section ____.<br/><b>Done checklist:</b> code/review, tests, ownership, bilingual states, responsive review, evidence, known issues.','BodyA'),P('Appendix B. Sprint planning and close-out record template','H1A')]
